window.CAPS_SEARCH = [{"url":"index.html","title":"홈","desc":"우리교회지원센터가 하는 일을 한눈에","cat":"페이지","kw":"처음 메인 홈"},{"url":"about.html","title":"센터 소개","desc":"어떤 사람들이 무엇을 위해 모였는지","cat":"페이지","kw":"소개 우리 누구"},{"url":"services/index.html","title":"지원 항목 전체","desc":"센터가 해 드리는 일 전부","cat":"페이지","kw":"서비스 목록"},{"url":"process.html","title":"이용 절차","desc":"신청부터 시작까지 어떻게 진행되는지","cat":"페이지","kw":"순서 진행 방법"},{"url":"faq.html","title":"자주 묻는 질문","desc":"많이 물어보시는 것들을 모았습니다","cat":"페이지","kw":"FAQ 질문"},{"url":"contact.html","title":"문의","desc":"전화 · 카카오톡 · 이메일로 여쭤보기","cat":"페이지","kw":"연락처 상담 전화"},{"url":"apply.html","title":"지원 신청","desc":"필요한 것을 적어 보내 주시면 연락드립니다","cat":"페이지","kw":"신청서 접수"},{"url":"status.html","title":"신청 현황","desc":"내가 넣은 신청이 어디까지 갔는지","cat":"페이지","kw":"진행 상황 조회"},{"url":"privacy.html","title":"개인정보 처리방침","desc":"무엇을 받아 두고 언제 지우는지","cat":"페이지","kw":"개인정보 방침 약관 수집 보관 삭제 탈퇴"},{"url":"services/index.html#face","title":"보이는 교회","desc":"교회의 처음 보이는 공간을 만듭니다","cat":"갈래","kw":"홈페이지에서 예배 시간을 확인하고, 현수막을 보고 찾아옵니다. 교회를 처음 만나는 자리를 만듭니다."},{"url":"services/index.html#ministry","title":"사역하는 교회","desc":"교회 사역의 구조를 함께 만듭니다","cat":"갈래","kw":"예배와 캠프 — 사람이 모이는 자리를 준비합니다. 소리가 또렷해야 말씀이 들리고, 캠프는 미리 준비해야 다음 세대가 남습니다."},{"url":"services/index.html#admin","title":"세우는 교회","desc":"예배 자료부터 행정 시스템까지 만들어 드립니다","cat":"갈래","kw":"서류는 휴대폰으로 오가고, 예배 공간은 교회끼리 주고받습니다. 눈에 잘 띄지 않지만 막히면 사역 전체가 멈추는 일들입니다."},{"url":"services/index.html#community","title":"커뮤니티 센터","desc":"목회자와 교역자가 서로 잇는 자리입니다","cat":"갈래","kw":"사역 광고와 연합 모임, 꿀팁과 중보 기도요청을 나눕니다. 가입은 무료입니다."},{"url":"services/homepage.html","title":"홈페이지 제작","desc":"처음 찾아오는 사람이 가장 먼저 보는 교회의 얼굴","cat":"지원 항목","kw":"홈페이지 예배 시간과 오시는 길, 교회 소개와 설교 영상을 담습니다. 고칠 곳이 생기면 말씀만 주세요 — 교회에서 직접 다루실 일이 없습니다. 반응형 디자인 설교 영상 연동 교회 소개 · 오시는 길 주소 · 서버 관리 반응형 홈페이지 일체 (PC · 모바일) 주소 연결 및 SSL 보안 인증서 설정 (도메인 구입비는 교회 부담, 무료 주소도 가능) 오픈 후 지원 기간 내 수정 · 장애 대응 검색해도 정보가 안 나옵니다 만들어 둔 홈페이지가 방치돼 있습니다 휴대폰에서 글씨가 깨집니다 웹사이트 홈피 사이트 도메인 제작 만들기"},{"url":"services/design.html","title":"마케팅 지원","desc":"현수막 · 포스터 · 주보부터 SNS 채널 개설까지","cat":"지원 항목","kw":"마케팅 절기 현수막부터 매주 나가는 주보까지, 교회에서 되풀이해 필요한 디자인을 만들어 드립니다. 완성된 인쇄용 파일을 드리고, 인쇄와 배송은 교회에서 편한 곳에 맡기시면 됩니다. 주보 정기 제작 절기 현수막 · 배너 행사 포스터 · 초청장 교회 기본 디자인 정리 수정 가능한 템플릿 인쇄소에 바로 넘길 수 있는 파일 SNS 계정 개설 · 초기 세팅 SNS 콘텐츠 제작 · 운영 안내 인쇄용 원본 파일 (PDF · 고해상도, 재단 여백 포함) 온라인 공유용 이미지 (카카오톡 · SNS 규격) 교회에서 직접 수정할 수 있는 템플릿 파일 채널을 열어 드린 경우 — 아이디 · 비밀번호와 초기 설정 안내 매주 주보 만드는 일이 부담입니다 절기마다 급하게 업체를 찾습니다 만드는 사람마다 느낌이 다릅니다 현수막 배너 포스터 명함 로고 인쇄 디자인"},{"url":"services/sound.html","title":"음향 세팅","desc":"설교가 또렷하게 들리는 예배당","cat":"지원 항목","kw":"음향 예배당 음향 진단부터 장비 선정과 설치까지 지원합니다. 온라인 송출을 위한 음향 구성도 함께 잡아 드립니다. 현장 음향 진단 장비 선정 · 견적 설치 · 배선 기본 세팅 잡기 온라인 송출 음향 봉사자 인수인계 현장 진단과 개선 제안 (예산별 선택지 포함) 장비 설치 및 배선 정리 예배에 맞춘 기본 세팅 봉사자 인수인계 (설치 현장에서) 뒷자리에서 설교가 잘 안 들립니다 찬양 때마다 하울링이 납니다 온라인 송출 소리가 좋지 않습니다 스피커 마이크 믹서 앰프 소리 하울링 음향장비 설치"},{"url":"services/akc.html","title":"AKC","desc":"어라이즈 코리아 캠프 — 여름 · 겨울에 열립니다","cat":"지원 항목","kw":"AKC AKC(Arise Korea Camp)는 무너진 이 땅의 다음 세대와 청년을 깨우는 캠프입니다. 여름과 겨울 방학에 맞춰 경기도 안성 AKC 수련원에서 열리며, 개인 또는 교회 단위로 등록해 참석하십니다. 준비할 인력이 없는 교회도 참가 신청만으로 이용하실 수 있습니다. 등록만 하시면 됩니다 여름 · 겨울 두 시즌 대상별 영성캠프 영역캠프 — 일터와 학교로 캠프 이후를 잇는 앱 소수 인원도 참가 캠프 참가 (프로그램 · 숙식 포함) 참가 안내문 및 보호자 동의서 서식 현장 운영과 안전 관리 캠프 사진 및 정리 자료 수련회를 준비할 사람이 없습니다 우리 교회 인원만으로는 모이지 않습니다 은혜가 3일로 끝납니다 수련회 집회 컨퍼런스 대회"},{"url":"services/smartchurch.html","title":"스마트처치 앱","desc":"성도의 휴대폰 안에 들어가는 교회","cat":"지원 항목","kw":"스마트처치 주보, 예배 영상, 공지, 출석, 심방 기록까지 하나의 앱으로 정리합니다. 성도용 앱과 교역자용 관리 화면을 함께 제공합니다. 주보 · 공지 알림 예배 영상 · 설교 노트 교적 관리 출석 체크 심방 · 목양 기록 헌금 · 재정 안내 성도용 앱 (iOS · Android) 교역자용 관리 화면 및 권한 설정 기존 교적 데이터 이전 교역자 교육 및 성도 가입 안내물 공지가 단체 채팅방에 묻힙니다 성도 명단이 엑셀 파일로만 있습니다 출석과 심방 기록이 흩어져 있습니다 앱 어플 모바일 주보앱 출석"},{"url":"services/intooffice.html","title":"인투오피스","desc":"교회 서류에 도장 받으러 다니지 마세요 — 전자서명","cat":"지원 항목","kw":"인투오피스 근로계약서, 참가 동의서, 지출 결의, 시설 사용 승낙까지. 교회에서 서명이 필요한 모든 문서를 휴대폰으로 주고받고, 자동으로 보관하고, 필요할 때 바로 찾는 전자서명 서비스입니다. 종이와 도장, 그리고 \"그 서류 어디 있죠?\" 를 함께 없앱니다. 카톡으로 보내고, 1분 만에 서명 누가 안 했는지 한눈에 서명 시각까지 남는 증거 자료 정리 · 보관은 프로그램이 자주 쓰는 서식 그대로 권한을 나눠서 교회 전용 전자서명 계정 문서 서식 등록 및 보관 공간 서명 진행 상황 확인 · 미완료자 재알림 서명 이력(시각 · 기기 정보)이 포함된 완료 문서 문서 검색 · 분류 · 내려받기 서명 하나 받으려고 주일까지 기다립니다 작년 서류를 아무도 못 찾습니다 문제가 생겼을 때 증명할 게 없습니다 행정 서류 결재 문서 전자결재 사무"},{"url":"services/sharing.html","title":"소그룹 나눔집","desc":"설교 원고를 넣으면, 이번 주 나눔집이 나옵니다","cat":"지원 항목","kw":"나눔집 그 주 설교 원고를 붙여넣으시면 요약과 나눔 질문, 기도 제목이 담긴 소그룹 나눔집이 만들어집니다. 화면에서 고치신 뒤 PDF 로 내려받아 그대로 인쇄해 쓰시면 됩니다. 그 교회 설교로 만듭니다 원고가 없어도 됩니다 들어가는 것 화면에서 고치고 내려받기 교단에 맞춘 표현 리더 팁 소그룹 나눔집 PDF (A4 1~2장) 리더용 진행 팁이 포함된 판본 교회에서 문구를 고칠 수 있는 편집 화면 소그룹 리더가 매주 몇 시간을 씁니다 설교와 나눔이 따로 놉니다 나눔의 깊이가 조마다 다릅니다 나눔집 소그룹 교재 순모임 성경공부"},{"url":"services/community.html","title":"커뮤니티 센터","desc":"목회자와 교역자가 서로 잇는 자리 — 가입 무료","cat":"지원 항목","kw":"커뮤니티 사역 광고와 연합 모임, 현장에서 얻은 꿀팁과 중보 기도요청을 나누는 곳입니다. 패키지에 가입하지 않으셔도 무료로 쓰실 수 있습니다. 사역 광고 연합 모임 꿀팁 공유 중보 기도요청 컨테스트 가입 무료 커뮤니티 게시판 이용 (사역 광고 · 연합 모임 · 꿀팁 · 중보 기도) 부동산 매물 게시판 열람 소그룹 나눔집 맛보기 물어볼 곳이 없습니다 작은 교회 혼자서는 못 하는 일이 있습니다 기도를 부탁할 자리가 마땅치 않습니다 커뮤니티 모임 기도요청 중보 광고"},{"url":"listings.html","title":"부동산 매물","desc":"예배 공간 매매 · 임대","cat":"게시판","kw":"교회 매매 임대 상가 건물 부동산 매물 이전 예배당 자리"},{"url":"market.html","title":"중고 장터","desc":"음향 · 악기 · 집기 (설치는 별도)","cat":"게시판","kw":"중고 스피커 마이크 믹서 앰프 악기 피아노 의자 강대상 싸게 사기 팔기"},{"url":"jobs.html","title":"교역자 구인","desc":"교회가 올리고, 직접 지원","cat":"게시판","kw":"전도사 목사 반주자 찬양인도자 간사 채용 구인 구직 사역지 청빙 사택 사례비 교역자 부교역자 교육전도사"},{"url":"guesthouse.html","title":"게스트하우스","desc":"교회가 내어 주는 방","cat":"게시판","kw":"사택 선교관 숙소 숙박 방 머물 곳 선교사 유학생 게스트하우스 잠자리"},{"url":"tickets.html","title":"집회 티켓팅","desc":"찬양집회 · 수련회 신청","cat":"게시판","kw":"집회 수련회 세미나 예매 티켓 신청 참가 좌석"},{"url":"listings.html#new","title":"매물 올리기","desc":"교회 부동산을 게시판에 내놓기","cat":"게시판","kw":"등록 매매 임대"},{"url":"market.html#new","title":"중고 물품 팔기","desc":"쓰던 음향 · 악기 · 집기를 내놓기","cat":"게시판","kw":"등록 판매 중고"},{"url":"market.html#install","title":"설치 대행 신청","desc":"사 오신 장비를 예배당에 달아 드립니다 (별도 비용)","cat":"게시판","kw":"음향 설치 시공 견적"},{"url":"guesthouse.html#new","title":"방 내어 놓기","desc":"비어 있는 사택 · 선교관을 나누기","cat":"게시판","kw":"등록 숙소"},{"url":"tickets.html#new","title":"집회 등록하기","desc":"집회 · 수련회 신청을 받기","cat":"게시판","kw":"등록 예매 티켓"},{"url":"jobs.html#new","title":"구인 공고 올리기","desc":"우리 교회에서 함께할 사역자를 찾기","cat":"게시판","kw":"등록 채용 모집 전도사"},{"url":"jobs.html","title":"사역자 자리 찾기","desc":"교회들이 올린 구인 공고 보기","cat":"게시판","kw":"취업 지원 사역지 청빙"},{"url":"pricing.html","title":"비용이 얼마인가요","desc":"항목마다 다릅니다. 무엇이 필요하신지 알려 주시면 견적을 내어 드립니다 — 상담은 무료입니다.","cat":"자주 찾는 것","kw":"요금 가격 비용 값 얼마 견적 금액 무료 돈 월 관리비 패키지 요금제"},{"url":"status.html","title":"내 신청이 어디까지 갔나요","desc":"넣으신 신청의 진행 상황을 확인하실 수 있습니다.","cat":"자주 찾는 것","kw":"조회 확인 진행 접수 신청현황"},{"url":"faq.html#faq-common-0","title":"항목마다 비용을 매기는 방식이 다른가요?","desc":"내는 방식이 세 가지입니다 — 매달 내는 것, 한 번 내는 것, 건마다 견적을 내는 것. 금액은 지금 다시 정하고 있어 이 자리에 올려 두지 못했습니다. 필요하신 항목을 말씀해 주시면 견적을 내어 드립니다 — 상담과 견적에는 비용이 들지 않습니다. 게시판은 따로입니다 — 중고 장터 · 교역자 구인 · 게스트하우스 · 집회 티켓팅은 무료이고, 부동산 매물은 서류를 확인한 뒤에 등록비를 안내해 드립니다.","cat":"질문","kw":""},{"url":"faq.html#faq-common-1","title":"작은 교회도 신청할 수 있나요?","desc":"네. 규모 · 지역 · 교단에 제한이 없습니다. 오히려 담당 인력이 부족한 교회일수록 도움이 되는 항목이 많습니다. 상담 시 교인 수와 예산 범위를 알려주시면 그 안에서 가능한 방안을 정리해 드립니다.","cat":"질문","kw":""},{"url":"faq.html#faq-common-2","title":"상담과 견적에도 비용이 드나요?","desc":"상담과 견적 산출은 무료입니다. 비용은 제안서 내용에 합의하고 계약이 진행될 때부터 발생합니다.","cat":"질문","kw":""},{"url":"faq.html#faq-common-3","title":"여러 항목을 함께 신청해도 되나요?","desc":"가능합니다. 신청서에서 필요한 항목을 여러 개 선택하시면 전체를 묶어 조율합니다. 항목을 함께 진행하면 일정과 비용 모두 유리한 경우가 많습니다.","cat":"질문","kw":""},{"url":"faq.html#faq-common-4","title":"교단이나 소속을 따지나요?","desc":"따로 제한하지 않습니다. 한국 교회라면 교단·소속과 무관하게 신청하실 수 있습니다.","cat":"질문","kw":""},{"url":"faq.html#faq-common-5","title":"지방 교회도 지원되나요?","desc":"전국을 지원합니다. 음향 세팅처럼 현장 방문이 필요한 항목은 지역에 따라 일정이 달라질 수 있어, 상담 시 방문 가능일을 함께 안내드립니다.","cat":"질문","kw":""},{"url":"faq.html#faq-common-6","title":"신청 후 진행 상황은 어떻게 확인하나요?","desc":"접수 시 발급되는 접수번호로 조회할 수 있고, 배정된 담당자에게 직접 문의하셔도 됩니다.","cat":"질문","kw":""},{"url":"faq.html#faq-homepage-0","title":"기존 홈페이지 자료를 옮길 수 있나요?","desc":"가능합니다. 기존 사이트의 글과 사진을 확인한 뒤 옮길 수 있는 범위를 알려드립니다. 자료가 많으면 일부는 손으로 정리해야 할 수 있습니다.","cat":"질문","kw":"홈페이지 제작"},{"url":"faq.html#faq-homepage-1","title":"교회에 컴퓨터를 잘 다루는 사람이 없습니다.","desc":"교회에서 직접 다루실 일이 없습니다. 예배 시간이 바뀌었다거나 사진을 갈아 달라고 말씀만 주시면 저희가 고칩니다. 내용 수정은 월 관리비에 들어 있습니다.","cat":"질문","kw":"홈페이지 제작"},{"url":"faq.html#faq-homepage-2","title":"온라인 헌금 기능도 넣을 수 있나요?","desc":"헌금 계좌를 안내하는 화면은 넣어 드립니다. 카드 · 간편결제로 바로 내는 방식은 결제사 심사가 따로 있어, 필요하시면 상담 때 말씀해 주세요.","cat":"질문","kw":"홈페이지 제작"},{"url":"faq.html#faq-design-0","title":"SNS 채널은 누구 명의로 만드나요?","desc":"교회 명의로 만듭니다. 센터 계정으로 만들어 두면 나중에 교회가 되찾기 어려워집니다. 교회 이메일로 계정을 열고, 아이디와 비밀번호는 세팅이 끝나는 자리에서 그대로 넘겨 드립니다. 센터는 접속 권한을 남겨 두지 않습니다.","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-design-1","title":"유튜브와 인스타그램 중 무엇을 먼저 하면 좋을까요?","desc":"한 곳부터 하셔도 됩니다. 설교 영상이 있으시면 유튜브가, 소식과 사진 위주면 인스타그램이 먼저입니다. 교회 상황을 보고 무엇부터 여는 것이 나을지 함께 정해 드립니다. 열어만 두고 아무도 올리지 않는 계정이 여럿 있는 것보다, 한 곳을 꾸준히 하시는 편이 낫습니다.","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-design-2","title":"급하게 이번 주까지 필요한데 가능한가요?","desc":"항목과 현재 작업량에 따라 다릅니다. 신청서에 사용 일자를 적어주시면 가능 여부를 먼저 확인해 회신드립니다. 디자인을 받으신 뒤 인쇄에 다시 며칠이 걸리니, 사용일에서 넉넉히 앞당겨 신청해 주세요.","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-design-3","title":"수정은 몇 번까지 되나요?","desc":"시안당 2회 수정이 기본이며, 그 이상은 협의합니다. 처음에 원하시는 분위기와 참고 이미지를 주시면 수정 횟수를 줄일 수 있습니다.","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-design-4","title":"교회 로고가 없는데 만들 수 있나요?","desc":"가능합니다. 로고 제작은 별도 항목으로 진행하며, 제작 후에는 현수막·주보 등 모든 인쇄물에 일관되게 적용됩니다.","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-design-5","title":"인쇄까지 맡길 수는 없나요?","desc":"인쇄소에 그대로 넘길 수 있는 파일을 드립니다 — 규격과 재단 여백, 색상까지 맞춰 두기 때문에 가까운 인쇄소에 파일만 보내시면 됩니다. 인쇄소에서 되묻거나 다시 손보는 일이 없습니다. 현수막은 실사 출력 업체, 주보는 동네 인쇄소면 충분하고, 어디에 맡길지 모르시겠다면 상담 때 일반적인 규격과 대략적인 비용을 알려드립니다. (인쇄비 · 배송비는 별도입니다.)","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-design-6","title":"인쇄했더니 색이 화면과 다릅니다.","desc":"인쇄 색상은 종이와 장비에 따라 달라집니다. 파일은 인쇄용 색상 기준(CMYK)으로 드리지만, 중요한 인쇄물은 인쇄소에 시험 출력을 요청해 확인하신 뒤 본 인쇄를 하시길 권합니다.","cat":"질문","kw":"마케팅 지원"},{"url":"faq.html#faq-sound-0","title":"장비를 새로 사야만 하나요?","desc":"아닙니다. 배치와 설정 조정만으로 개선되는 경우가 적지 않습니다. 진단 단계에서 기존 장비로 가능한 범위를 먼저 알려드리고, 교체가 필요한 항목만 구분해 제안합니다.","cat":"질문","kw":"음향 세팅"},{"url":"faq.html#faq-sound-1","title":"설치 때 예배를 쉬어야 하나요?","desc":"평일에 진행하며 주일 예배에 지장이 없도록 일정을 잡습니다. 규모가 큰 공사는 단계를 나눠 진행할 수 있습니다.","cat":"질문","kw":"음향 세팅"},{"url":"faq.html#faq-sound-2","title":"지방인데 방문이 가능한가요?","desc":"지역에 따라 방문 일정과 출장 조건이 달라집니다. 신청 시 지역을 알려주시면 가능한지 함께 안내드립니다.","cat":"질문","kw":"음향 세팅"},{"url":"faq.html#faq-akc-0","title":"캠프는 어디서 열리나요?","desc":"AKC 수련원입니다 — 경기도 안성시 이현배티길 58-30. 캠프에 따라 장소가 달라지는 경우가 있어, 확정 장소는 AKC 홈페이지의 캠프별 안내에서 확인해 주세요.","cat":"질문","kw":"AKC"},{"url":"faq.html#faq-akc-1","title":"어떻게 신청하나요?","desc":"캠프별 등록은 AKC 홈페이지의 등록 폼에서 진행합니다. 어떤 캠프가 맞을지 모르시겠으면 우리교회지원센터 신청서에서 AKC를 선택하시고 대상과 희망 시기, 인원을 적어주시면 담당자가 연락드려 함께 정리해 드립니다.","cat":"질문","kw":"AKC"},{"url":"faq.html#faq-akc-2","title":"캠프는 언제 열리나요?","desc":"여름과 겨울 방학에 맞춰 열립니다. 확정된 일정과 등록 안내는 AKC 홈페이지에 올라오며, 이 페이지의 [AKC 공식 홈페이지] 버튼으로 바로 가실 수 있습니다.","cat":"질문","kw":"AKC"},{"url":"faq.html#faq-akc-3","title":"어떤 교회가 참가할 수 있나요?","desc":"규모와 교단에 제한을 두지 않습니다. 인원이 적은 교회도 참가할 수 있도록 여러 교회가 함께 모이는 방식으로 진행합니다.","cat":"질문","kw":"AKC"},{"url":"faq.html#faq-akc-4","title":"교회에서 준비해야 할 것은 무엇인가요?","desc":"참가 인원과 인솔자 명단, 그리고 참가자 동의서 회수입니다. 장소와 강사, 프로그램과 진행은 AKC 팀이 맡습니다.","cat":"질문","kw":"AKC"},{"url":"faq.html#faq-akc-5","title":"캠프가 끝난 뒤에는 어떻게 이어지나요?","desc":"AKC 앱을 통해 캠프의 은혜가 일상으로 이어지도록 돕습니다. 신앙·시간관리, 지역교회 양육 연계, 청소년 학업·진로와 청년 취업까지 이어지는 디지털 신앙 생태계를 준비하고 있습니다.","cat":"질문","kw":"AKC"},{"url":"faq.html#faq-smartchurch-0","title":"어르신 성도가 사용할 수 있을까요?","desc":"앱 설치와 로그인 과정을 최대한 줄였고, 글자 크기를 키울 수 있습니다. 설치 안내물을 인쇄물로 함께 드리며, 앱을 쓰지 않는 성도에게는 기존 방식으로 안내가 나가도록 병행 운영할 수 있습니다.","cat":"질문","kw":"스마트처치 앱"},{"url":"faq.html#faq-smartchurch-1","title":"성도 개인정보는 안전한가요?","desc":"교적 정보는 권한을 가진 교역자만 볼 수 있도록 나뉘어 있고, 접근 기록이 남습니다. 개인정보 수집·이용 동의 양식도 함께 제공해 교회가 절차를 갖추도록 돕습니다.","cat":"질문","kw":"스마트처치 앱"},{"url":"faq.html#faq-smartchurch-2","title":"홈페이지가 이미 있는데 앱도 필요한가요?","desc":"홈페이지는 외부에 교회를 알리는 창구이고, 앱은 등록 성도와 소통하는 도구로 역할이 다릅니다. 두 항목을 함께 진행하면 주보와 공지가 양쪽에 자동으로 반영되도록 연동할 수 있습니다.","cat":"질문","kw":"스마트처치 앱"},{"url":"faq.html#faq-intooffice-0","title":"전자서명이 도장만큼 효력이 있나요?","desc":"전자서명법은 전자서명이 전자적 형태라는 이유만으로 서명 · 기명날인으로서의 효력이 부인되지 않는다고 정하고 있습니다. 인투오피스는 서명한 시각과 기기 정보를 문서에 함께 남겨 나중에 확인할 수 있게 합니다. 다만 법으로 종이 원본이나 공증을 요구하는 문서(등기 등)는 예외이니, 해당 문서는 기존 방식대로 처리하셔야 합니다.","cat":"질문","kw":"인투오피스"},{"url":"faq.html#faq-intooffice-1","title":"어르신 성도도 쓸 수 있을까요?","desc":"받는 분은 앱을 깔거나 가입하지 않습니다. 문자로 온 링크를 눌러 화면에 손가락으로 이름을 쓰면 끝입니다. 글자 크기를 크게 잡아 두었고, 어려워하시면 담당자가 옆에서 화면을 같이 보며 진행하셔도 됩니다.","cat":"질문","kw":"인투오피스"},{"url":"faq.html#faq-intooffice-2","title":"회계 정리나 급여 처리도 해 주시나요?","desc":"인투오피스는 교회가 직접 쓰시는 전자서명 · 문서 보관 프로그램입니다. 회계와 신고 업무 자체를 대신하지는 않지만, 그 과정에서 오가는 서류는 인투오피스로 훨씬 빠르게 처리하실 수 있습니다 — 지출 결의서 하나에 도장 받으러 다니지 않으셔도 됩니다.","cat":"질문","kw":"인투오피스"},{"url":"faq.html#faq-intooffice-3","title":"기존 서류는 어떻게 하나요?","desc":"이미 종이로 받아 두신 서류는 사진이나 스캔 파일로 올려 함께 보관하실 수 있습니다. 앞으로 나갈 문서부터 전자서명으로 바꾸시면 됩니다. 한 번에 다 옮기지 않으셔도 됩니다.","cat":"질문","kw":"인투오피스"},{"url":"faq.html#faq-intooffice-4","title":"문서가 새어 나가지는 않나요?","desc":"문서는 링크를 받은 당사자와 교회 계정에서만 열립니다. 누가 열람하고 누가 보낼 수 있는지 권한을 나눌 수 있고, 완료된 문서의 열람 기록도 남습니다.","cat":"질문","kw":"인투오피스"},{"url":"faq.html#faq-intooffice-5","title":"중간에 그만두면 문서는 어떻게 되나요?","desc":"해지하시기 전에 보관된 문서를 모두 내려받으실 수 있습니다. 교회 자료는 교회 것입니다.","cat":"질문","kw":"인투오피스"},{"url":"faq.html#faq-sharing-0","title":"설교 원고를 따로 쓰지 않습니다.","desc":"개요만 있거나 원고 없이 설교하시는 분이 많습니다. 그런 경우 설교 영상이나 음성 링크를 주시면 거기서 원고를 뽑아 나눔집을 만듭니다.","cat":"질문","kw":"소그룹 나눔집"},{"url":"faq.html#faq-sharing-1","title":"만들어진 질문이 우리 교회와 안 맞으면요?","desc":"화면에서 고치시면 됩니다. 질문을 바꾸고 지우고 더하실 수 있고, 그렇게 손보신 것이 PDF 에 담깁니다. 교회 정보에 교단을 적어 두시면 처음부터 그 결에 맞게 나옵니다.","cat":"질문","kw":"소그룹 나눔집"},{"url":"faq.html#faq-sharing-2","title":"성경 본문도 나눔집에 들어가나요?","desc":"장 · 절만 표기하고 본문 전문은 넣지 않습니다. 개역개정 본문은 대한성서공회 저작권이라 인쇄해 배포하면 문제가 됩니다. 나눔 자리에서 성경을 함께 펴서 읽으시는 편이 낫기도 합니다.","cat":"질문","kw":"소그룹 나눔집"},{"url":"faq.html#faq-sharing-3","title":"설교 원고가 밖으로 새지 않나요?","desc":"나눔집을 만드는 데만 쓰고, 다른 교회에 보여 드리거나 학습에 쓰지 않습니다. 교회가 직접 지우실 수 있습니다.","cat":"질문","kw":"소그룹 나눔집"},{"url":"faq.html#faq-community-0","title":"정말 무료인가요?","desc":"무료입니다. 커뮤니티에서 목회자들이 서로 도우면 그 자체로 의미가 있고, 필요가 생긴 교회가 나중에 패키지를 보시면 됩니다.","cat":"질문","kw":"커뮤니티 센터"},{"url":"faq.html#faq-community-1","title":"성도도 가입할 수 있나요?","desc":"목회자 · 교역자를 위한 자리라 확인 절차를 둡니다. 기도 제목과 사역 고민이 오가는 곳이라 그렇습니다.","cat":"질문","kw":"커뮤니티 센터"},{"url":"faq.html#faq-community-2","title":"올린 글을 교회 밖에서 볼 수 있나요?","desc":"커뮤니티 글은 가입한 목회자 · 교역자에게만 보입니다. 검색에 노출되지 않습니다.","cat":"질문","kw":"커뮤니티 센터"}];
